self.addEventListener("push", (event) => {
  let payload = {}

  if (event.data) {
    try {
      payload = event.data.json()
    } catch (error) {
      payload = { title: "Fizzy", body: event.data.text() }
    }
  }

  const title = payload.title || "Fizzy"
  const options = {
    body: payload.body || "",
    icon: payload.icon || "/app-icon-192.png",
    badge: "/app-icon-192.png",
    tag: payload.tag,
    renotify: Boolean(payload.tag),
    data: { url: payload.url }
  }

  event.waitUntil(self.registration.showNotification(title, options))
})

self.addEventListener("notificationclick", (event) => {
  event.notification.close()

  const url = event.notification.data && event.notification.data.url
  if (!url) return

  event.waitUntil(self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((windowClients) => {
    const existing = windowClients.find((client) => client.url.includes(url))
    if (existing) return existing.focus()
    return self.clients.openWindow(url)
  }))
})
